svg.script:
(function(){
  var rs = document.querySelectorAll('#tocHits rect');
  for (var i = 0; i < rs.length; i++) {
    rs[i].addEventListener('click', function () {
      var p = parseInt(this.getAttribute('data-p'), 10);
      if (!p) return;
      try { if (window.parent && window.parent !== window) window.parent.postMessage({ zrh: 'goto', p: p }, '*'); } catch (e) {}
    });
  }
})();
